// Helper: dapatkan kode bulan kalender aktif saat ini (contoh: "2026-10")
function getCurrentMonthKey() {
  const now = new Date();
  const y = now.getFullYear();
  const m = String(now.getMonth() + 1).padStart(2, '0');
  return `${y}-${m}`;
}

// Helper: cek apakah seorang pelanggan berhak mendapatkan kuota voucher
function isCustomerEligibleForVoucher(customer) {
  if (!customer) return false;
  if (loyaltySettings.voucherTarget === 'all') return true;
  // Jika 'selected', hanya jika isVoucherEligible bernilai true (default true bila belum diset)
  return customer.isVoucherEligible !== false;
}

// Helper: hitung data voucher bulanan pelanggan (kuota, used, remaining)
function getCustomerMonthlyVoucherStats(customer, monthKey = getCurrentMonthKey()) {
  if (!customer || !isCustomerEligibleForVoucher(customer)) {
    return { quota: 0, used: 0, remaining: 0, eligible: false };
  }
  const quota = parseInt(loyaltySettings.voucherMonthlyQuota) || 0;
  const usageObj = (customer.voucherUsage && customer.voucherUsage[monthKey]) || { used: 0, transactions: [] };
  const used = parseInt(usageObj.used) || 0;
  const remaining = Math.max(0, quota - used);
  return { quota, used, remaining, eligible: true };
}

function saveCustomVouchersLocally() {
  localStorage.setItem('kasir_custom_vouchers', JSON.stringify(customVouchers));
  if (firebaseDb && typeof getStorePath === 'function') {
    try {
      firebaseDb.ref(getStorePath('customVouchers')).set(customVouchers).catch(err => {
        console.warn('⚠️ Gagal sync customVouchers ke cloud:', err.message);
      });
    } catch (e) {
      console.warn('⚠️ Error sinkronisasi customVouchers ke cloud:', e);
    }
  }
}

// Cek apakah voucher custom aktif pada tanggal/waktu tertentu
function isCustomVoucherActive(v, targetDateStr = getLocalISODate()) {
  if (!v) return false;
  if (v.tipeKadaluarsa === 'tanpa_kadaluarsa' || !v.tanggalKadaluarsa) return true;
  return v.tanggalKadaluarsa >= targetDateStr;
}

// Ambil semua alokasi voucher custom milik seorang anggota tertentu
function getCustomerCustomVouchers(customer) {
  if (!customer) return [];
  const custId = String(customer.id || '');
  const custCode = String(customer.kode_anggota || customer.id || '');
  const custName = String(customer.nama || '').toLowerCase().trim();
  
  const results = [];
  customVouchers.forEach(v => {
    if (!Array.isArray(v.allocations)) return;
    v.allocations.forEach(alloc => {
      const aId = String(alloc.anggotaId || '');
      const aName = String(alloc.anggotaNama || '').toLowerCase().trim();
      if (aId === custId || aId === custCode || (aName && aName === custName)) {
        results.push({
          voucherId: v.id,
          namaVoucher: v.namaVoucher,
          kategori: v.kategori || 'Umum',
          tanggalMulai: v.tanggalMulai || '',
          tipeKadaluarsa: v.tipeKadaluarsa || 'tanpa_kadaluarsa',
          tanggalKadaluarsa: v.tanggalKadaluarsa || null,
          nominal: parseInt(alloc.nominal) || 0,
          status: alloc.status || 'belum_diambil', // 'belum_diambil' | 'sudah_diambil'
          tanggalAmbil: alloc.tanggalAmbil || null,
          txId: alloc.txId || null,
          isExpired: !isCustomVoucherActive(v)
        });
      }
    });
  });
  return results;
}

// Cek apakah alokasi voucher lolos filter periode yang dipilih user pada tab Anggota
function isCustomVoucherAllocationInFilter(allocItem) {
  // Filter Spesifik Nama Voucher (e.g. "Voucher Ramadhan")
  if (currentVoucherNameFilter && currentVoucherNameFilter !== 'All') {
    if ((allocItem.namaVoucher || '').toLowerCase().trim() !== currentVoucherNameFilter.toLowerCase().trim()) {
      return false;
    }
  }

  // Filter Kategori Voucher (jika masih digunakan)
  if (currentVoucherCategoryFilter && currentVoucherCategoryFilter !== 'All') {
    if ((allocItem.kategori || 'Umum').toLowerCase() !== currentVoucherCategoryFilter.toLowerCase()) {
      return false;
    }
  }

  // Filter Status: sudah ambil vs belum ambil
  if (currentCustomerVoucherFilter === 'used' && allocItem.status !== 'sudah_diambil') return false;
  if (currentCustomerVoucherFilter === 'unused' && allocItem.status !== 'belum_diambil') return false;

  const startD = document.getElementById('voucher-filter-date-start')?.value || '';
  const endD = document.getElementById('voucher-filter-date-end')?.value || '';
  if (startD || endD) {
    const refDate = allocItem.status === 'sudah_diambil' ? (allocItem.tanggalAmbil || allocItem.tanggalMulai || '') : (allocItem.tanggalMulai || '');
    if (refDate) {
      const onlyD = refDate.slice(0, 10);
      if (startD && onlyD < startD) return false;
      if (endD && onlyD > endD) return false;
    }
  }

  return true;
}

function resetVoucherDateRangeFilter() {
  const startInp = document.getElementById('voucher-filter-date-start');
  const endInp = document.getElementById('voucher-filter-date-end');
  const catSel = document.getElementById('voucher-filter-category-select');
  const nameSel = document.getElementById('voucher-filter-name-select');
  if (nameSel) nameSel.value = 'All';
  currentVoucherNameFilter = 'All';
  if (startInp) startInp.value = '';
  if (endInp) endInp.value = '';
  if (catSel) catSel.value = 'All';
  currentCustomerVoucherFilter = 'all';
  currentVoucherCategoryFilter = 'All';
  setVoucherTableFilter('all');
}

// --- Helper Gambar (Google Drive Direct URL, Dropbox, Imgur, Offline Fallback) ---
function normalizeImageUrl(url) {
  if (!url || typeof url !== 'string') return '';
  let cleanUrl = url.trim();

  // 1. Google Drive Link: Konversi link view / sharing ke direct thumbnail image stream
  // Format contoh:
  // https://drive.google.com/file/d/1EtVgshFY84BznfWiXXpx1cpuKDLFqoOO/view?usp=drive_link
  // https://drive.google.com/open?id=1EtVgshFY84BznfWiXXpx1cpuKDLFqoOO
  // https://drive.google.com/uc?id=1EtVgshFY84BznfWiXXpx1cpuKDLFqoOO
  if (cleanUrl.includes('drive.google.com')) {
    let fileId = null;
    const matchFileD = cleanUrl.match(/\/file\/d\/([a-zA-Z0-9_-]+)/);
    if (matchFileD && matchFileD[1]) {
      fileId = matchFileD[1];
    } else {
      const matchIdParam = cleanUrl.match(/[?&]id=([a-zA-Z0-9_-]+)/);
      if (matchIdParam && matchIdParam[1]) {
        fileId = matchIdParam[1];
      }
    }
    if (fileId) {
      // Menggunakan endpoint lh3.googleusercontent.com yang sangat cepat, andal, dan tidak diblokir CORS
      return `https://lh3.googleusercontent.com/d/${fileId}`;
    }
  }

  // 2. Dropbox Link: ubah dl=0 jadi raw=1
  if (cleanUrl.includes('dropbox.com') && cleanUrl.includes('dl=0')) {
    return cleanUrl.replace('dl=0', 'raw=1');
  }

  return cleanUrl;
}

function handleImageError(img) {
  if (!img) return;
  // Coba fallback kedua jika gambar dari Google Drive gagal load via lh3 (misal file permission private)
  const originalSrc = img.getAttribute('data-original-src') || img.src;
  if (originalSrc && originalSrc.includes('lh3.googleusercontent.com/d/')) {
    const fileId = originalSrc.split('/d/')[1];
    if (fileId && !img.hasAttribute('data-tried-uc')) {
      img.setAttribute('data-tried-uc', 'true');
      img.src = `https://drive.google.com/uc?export=view&id=${fileId}`;
      return;
    }
  }

  img.onerror = null; // Mencegah loop tak terbatas
  img.src = 'data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" fill="none" stroke="%23cbd5e1" stroke-width="2"><rect width="100" height="100" fill="%23f8fafc"/><circle cx="50" cy="45" r="15"/><path d="M20,80 C20,60 80,60 80,80"/></svg>';
  img.style.cursor = 'default';
  img.onclick = null;
}

// Buka dialog lightbox perbesar gambar produk
function openProductImageLightbox(src, name = 'Gambar Produk') {
  if (!src || src.includes('data:image/svg+xml')) return;
  const directSrc = normalizeImageUrl(src);
  const modal = document.getElementById('product-image-lightbox-modal');
  const img = document.getElementById('lightbox-img');
  const caption = document.getElementById('lightbox-caption');
  if (modal && img) {
    img.setAttribute('data-original-src', directSrc);
    img.src = directSrc;
    if (caption) caption.textContent = name;
    modal.classList.add('active');
    modal.style.display = 'flex';
  }
}

// Tutup dialog lightbox perbesar gambar
function closeProductImageLightbox(event) {
  const modal = document.getElementById('product-image-lightbox-modal');
  if (modal) {
    modal.classList.remove('active');
    modal.style.display = 'none';
  }
}

function escapeJsQuotes(str) {
  if (!str) return '';
  return String(str).replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/"/g, '&quot;');
}
