// F. Fitur Saran Tambahan: Export Rekapitulasi ke File CSV / Excel
function exportSalesRekapCSV() {
  const dateStart = document.getElementById('sales-rekap-date-start')?.value || '';
  const dateEnd = document.getElementById('sales-rekap-date-end')?.value || '';
  const selectedSales = document.getElementById('sales-rekap-sales-target')?.value || 'All';

  let deliveries = salesDeliveries.filter(d => {
    if (selectedSales !== 'All' && d.salesId !== selectedSales) return false;
    if (dateStart && d.tanggal && d.tanggal < dateStart) return false;
    if (dateEnd && d.tanggal && d.tanggal > dateEnd) return false;
    return true;
  });

  let returns = salesReturns.filter(r => {
    if (selectedSales !== 'All' && r.salesId !== selectedSales) return false;
    if (dateStart && r.tanggal && r.tanggal < dateStart) return false;
    if (dateEnd && r.tanggal && r.tanggal > dateEnd) return false;
    return true;
  });

  if (deliveries.length === 0 && returns.length === 0) {
    alert('Tidak ada data transaksi untuk diekspor ke CSV.');
    return;
  }

  let csvContent = 'TANGGAL,TIPE,SALES,NO_NOTA_REFERENSI,RINCIAN_PRODUK,STATUS_BAYAR_GANTI,TOTAL_NILAI_RP\n';

  deliveries.forEach(d => {
    const itemsText = (d.items || []).map(i => `${i.nama} (${i.qty} pcs)`).join('; ');
    const sisa = (d.sisaTagihan !== undefined) ? d.sisaTagihan : (d.statusBayar === 'Tempo' ? d.grandTotal : 0);
    const statusText = sisa <= 0 ? 'Lunas' : `Tempo (Sisa ${sisa})`;
    csvContent += `"${d.tanggal}","Pembelian Masuk","${d.salesName}","${d.noNota}","${itemsText}","${statusText}",${d.grandTotal || 0}\n`;
  });

  returns.forEach(r => {
    const val = (r.qty || 0) * (r.hargaBeli || 0);
    csvContent += `"${r.tanggal}","Retur Produk","${r.salesName}","${r.alasan}","${r.productName} (${r.qty} pcs)","${r.status}",-${val}\n`;
  });

  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.setAttribute('href', url);
  const fileDateLabel = (dateStart && dateEnd) ? `${dateStart}_sd_${dateEnd}` : (dateStart || dateEnd || 'Semua');
  link.setAttribute('download', `Rekap_Sales_${fileDateLabel}.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
}

/* ==========================================================================
   G. FITUR MANAJEMEN CRM: RIWAYAT BELANJA, PENGINGAT WA VOUCHER, & BUKU HUTANG
   ========================================================================== */

let currentCustomerDebtFilter = 'all'; // 'all' | 'unpaid' | 'paid'
let currentActiveHistoryCustomerId = null;

// 1. Switcher Sub-View Pelanggan: Daftar Member vs Buku Hutang
async function switchCustomerSubView(subview) {
  const membersView = document.getElementById('cust-subview-members');
  const debtView = document.getElementById('cust-subview-debt');
  const btnMembers = document.getElementById('tab-btn-cust-members');
  const btnDebt = document.getElementById('tab-btn-cust-debt');

  if (subview === 'debt') {
    if (membersView) membersView.style.display = 'none';
    if (debtView) debtView.style.display = 'block';

    if (btnMembers) {
      btnMembers.style.background = 'transparent';
      btnMembers.style.color = '#64748b';
      btnMembers.style.boxShadow = 'none';
    }
    if (btnDebt) {
      btnDebt.style.background = '#ef4444';
      btnDebt.style.color = '#fff';
      btnDebt.style.boxShadow = '0 2px 6px rgba(239,68,68,0.3)';
    }
    renderCustomerDebtBook();
  } else {
    if (membersView) membersView.style.display = 'block';
    if (debtView) debtView.style.display = 'none';

    if (btnMembers) {
      btnMembers.style.background = '#ea580c';
      btnMembers.style.color = '#fff';
      btnMembers.style.boxShadow = '0 2px 6px rgba(234,88,12,0.3)';
    }
    if (btnDebt) {
      btnDebt.style.background = 'transparent';
      btnDebt.style.color = '#64748b';
      btnDebt.style.boxShadow = 'none';
    }
    renderCustomersTable();
  }
}


// 2. Filter Status Hutang Member
async function setCustomerDebtFilter(filter) {
  currentCustomerDebtFilter = filter;
  ['unpaid', 'paid', 'all'].forEach(f => {
    const btn = document.getElementById(`btn-debt-filter-${f}`);
    if (btn) {
      if (f === filter) {
        btn.style.background = (f === 'unpaid') ? '#ef4444' : ((f === 'paid') ? '#10b981' : '#ea580c');
        btn.style.color = '#fff';
      } else {
        btn.style.background = 'transparent';
        btn.style.color = '#64748b';
      }
    }
  });
  renderCustomerDebtBook();
}

// 3. Render Tabel & Ringkasan Buku Hutang Member
async function renderCustomerDebtBook() {
  const tbody = document.getElementById('customer-debt-table-body');
  if (!tbody) return;

  // Selalu ambil dari localStorage sebagai sumber paling akurat
  // (global transactions bisa kosong jika cloud sync belum selesai)
  let txSource = transactions;
  if (!txSource || txSource.length === 0) {
    try {
      const cached = localStorage.getItem('kasir_transactions');
      if (cached) {
        const parsed = JSON.parse(cached);
        if (Array.isArray(parsed) && parsed.length > 0) {
          txSource = parsed;
          transactions = parsed; // Update global
          console.log(`[DebtBook] Loaded ${txSource.length} tx from localStorage fallback`);
        }
      }
    } catch(e) { txSource = []; }
  }

  const dateStart = document.getElementById('filter-debt-date-start')?.value || '';
  const dateEnd = document.getElementById('filter-debt-date-end')?.value || '';
  const now = new Date();
  const todayStr = getLocalISODate(now).slice(0, 10);

  // Filter semua transaksi yang pernah/masih Bon:
  // - status_pembayaran === 'Bon'  (aktif Bon)
  // - sisa_piutang > 0             (masih punya sisa, walaupun status mungkin belum diupdate)
  // - riwayat_pelunasan.length > 0 (pernah Bon, sudah lunas sebagian/penuh)
  // - total > bayar (DP kurang dari total, ini data lama yang tidak punya sisa_piutang)
  let debtTxs = txSource.filter(tx => {
    if (tx.status_pembayaran === 'Bon') return true;
    if ((tx.sisa_piutang || 0) > 0) return true;
    if (Array.isArray(tx.riwayat_pelunasan) && tx.riwayat_pelunasan.length > 0) return true;
    // Tangkap data lama: transaksi yang bayar < total dan nama pelanggan diisi
    if (tx.nama_pelanggan && (tx.bayar || 0) < (tx.total || 0) && tx.status_pembayaran !== 'Lunas') return true;
    return false;
  });

  // Perbaiki data lama yang sisa_piutang-nya belum dihitung
  debtTxs = debtTxs.map(tx => {
    if ((tx.sisa_piutang === undefined || tx.sisa_piutang === null) && tx.status_pembayaran === 'Bon') {
      const bayar = tx.bayar || 0;
      const total = tx.total || 0;
      tx.sisa_piutang = Math.max(0, total - bayar);
    }
    return tx;
  });

  // Filter Rentang Tanggal jika dipilih (Tanggal Mulai s/d Tanggal Akhir)
  if (dateStart || dateEnd) {
    debtTxs = debtTxs.filter(tx => {
      if (!tx.waktu) return false;
      const tgl = parseTxDateStr(tx.waktu).slice(0, 10);
      if (dateStart && tgl < dateStart) return false;
      if (dateEnd && tgl > dateEnd) return false;
      return true;
    });
  }

  // Hitung ringkasan & Peringatan Jatuh Tempo
  let unpaidCount = 0, paidCount = 0, totalUnpaidRp = 0, totalPaidRp = 0;
  let overdueCount = 0, overdueTotalRp = 0;
  const uniqueDebtorsSet = new Set();

  debtTxs.forEach(tx => {
    const sisa = tx.sisa_piutang || 0;
    if (sisa > 0) {
      unpaidCount++;
      totalUnpaidRp += sisa;
      if (tx.nama_pelanggan) uniqueDebtorsSet.add(tx.nama_pelanggan);

      // Cek jatuh tempo
      if (tx.jatuh_tempo && tx.jatuh_tempo <= todayStr) {
        overdueCount++;
        overdueTotalRp += sisa;
      }
    } else {
      paidCount++;
      if (Array.isArray(tx.riwayat_pelunasan) && tx.riwayat_pelunasan.length > 0) {
        totalPaidRp += tx.riwayat_pelunasan.reduce((s, p) => s + (p.bayar || 0), 0);
      } else {
        totalPaidRp += (tx.total || 0);
      }
    }
  });

  // Update badge & summary
  const badgeTotalDebtors = document.getElementById('badge-total-debtors');
  const countUnpaidEl = document.getElementById('count-debt-unpaid');
  const countPaidEl = document.getElementById('count-debt-paid');
  const sumUnpaidEl = document.getElementById('summary-total-unpaid-debt');
  const sumPaidEl = document.getElementById('summary-total-paid-debt');
  const sumDebtorsCountEl = document.getElementById('summary-debtors-count');
  const overdueCountEl = document.getElementById('summary-overdue-debt-count');
  const overdueAmountEl = document.getElementById('summary-overdue-debt-amount');

  if (badgeTotalDebtors) badgeTotalDebtors.textContent = uniqueDebtorsSet.size;
  if (countUnpaidEl) countUnpaidEl.textContent = unpaidCount;
  if (countPaidEl) countPaidEl.textContent = paidCount;
  if (sumUnpaidEl) sumUnpaidEl.textContent = `Rp ${formatRupiah(totalUnpaidRp)}`;
  if (sumPaidEl) sumPaidEl.textContent = `Rp ${formatRupiah(totalPaidRp)}`;
  if (sumDebtorsCountEl) sumDebtorsCountEl.textContent = `${uniqueDebtorsSet.size} Pelanggan Masih Memiliki Hutang`;
  if (overdueCountEl) overdueCountEl.textContent = `${overdueCount} Tagihan`;
  if (overdueAmountEl) overdueAmountEl.textContent = `Rp ${formatRupiah(overdueTotalRp)} Perlu Ditagih Segera`;

  // Render Permohonan Hutang Masuk dari Anggota
  const appContainer = document.getElementById('container-member-debt-applications');
  const appListEl = document.getElementById('list-member-debt-applications');
  const appBadgeEl = document.getElementById('badge-debt-app-count');

  // Pastikan data customers sinkron dengan localStorage
  try {
    const cachedCust = localStorage.getItem('kasir_customers');
    if (cachedCust) {
      const parsed = JSON.parse(cachedCust);
      if (Array.isArray(parsed) && parsed.length > 0) customers = parsed;
    }
  } catch(e) {}

  if (appContainer && appListEl) {
    const pendingApps = [];
    customers.forEach(cust => {
      if (Array.isArray(cust.pengajuan_hutang)) {
        cust.pengajuan_hutang.forEach(app => {
          if (app.status === 'Menunggu Persetujuan Admin' || !app.status) {
            pendingApps.push({ ...app, custId: cust.id, custNama: cust.nama, custTelp: cust.telepon });
          }
        });
      }
    });

    if (pendingApps.length > 0) {
      appContainer.style.display = 'block';
      if (appBadgeEl) appBadgeEl.textContent = `${pendingApps.length} Permohonan Baru`;

      appListEl.innerHTML = pendingApps.map(app => {
        const tglStr = new Date(app.tanggal).toLocaleDateString('id-ID');
        return `
          <div style="background: #fff; border: 1px solid #fde68a; border-radius: 10px; padding: 0.85rem 1rem; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 0.75rem;">
            <div>
              <div style="display: flex; align-items: center; gap: 0.5rem;">
                <strong style="font-size: 0.95rem; color: #92400e;">${escapeHtml(app.custNama || 'Anggota')}</strong>
                <span style="font-size: 0.75rem; background: #fef3c7; color: #b45309; padding: 0.15rem 0.5rem; border-radius: 999px; font-weight: 700;">${app.custTelp || 'No HP -'}</span>
                <span style="font-size: 0.75rem; color: var(--text-muted);">Tgl Pengajuan: ${tglStr}</span>
              </div>
              <div style="font-size: 0.84rem; color: var(--text-main); margin-top: 0.25rem;">
                <b>Nominal:</b> <span style="font-size: 1.05rem; font-weight: 900; color: #dc2626; font-family: monospace;">Rp ${formatRupiah(app.nominal)}</span>
                <span style="margin-left: 0.75rem; color: var(--text-muted);">| <b>Alasan:</b> ${escapeHtml(app.alasan || '-')}</span>
                ${app.jatuh_tempo ? `<span style="margin-left: 0.5rem; color: #ea580c; font-weight: 700;">| Rencana Pelunasan: ${app.jatuh_tempo}</span>` : ''}
              </div>
            </div>
            <div style="display: flex; gap: 0.45rem;">
              <button type="button" onclick="approveMemberDebtApplication('${app.id}', '${app.custId}')" style="background: #15803d; color: #fff; border: none; font-weight: 800; font-size: 0.82rem; padding: 0.45rem 0.85rem; border-radius: 8px; cursor: pointer; display: inline-flex; align-items: center; gap: 0.35rem;">
                <span>✓ Setujui</span>
              </button>
              <button type="button" onclick="rejectMemberDebtApplication('${app.id}', '${app.custId}')" style="background: #dc2626; color: #fff; border: none; font-weight: 800; font-size: 0.82rem; padding: 0.45rem 0.85rem; border-radius: 8px; cursor: pointer; display: inline-flex; align-items: center; gap: 0.35rem;">
                <span>✕ Tolak</span>
              </button>
            </div>
          </div>
        `;
      }).join('');
    } else {
      appContainer.style.display = 'none';
    }
    checkAndNotifyPendingDebtApplications(false);
  }

  // Render Permohonan Klaim Poin Masuk dari Anggota
  const pointAppContainer = document.getElementById('container-member-point-applications');
  const pointAppListEl = document.getElementById('list-member-point-applications');
  const pointAppBadgeEl = document.getElementById('badge-point-app-count');

  if (pointAppContainer && pointAppListEl) {
    const pendingPointApps = [];
    customers.forEach(cust => {
      if (Array.isArray(cust.pengajuan_klaim_poin)) {
        cust.pengajuan_klaim_poin.forEach(clm => {
          if (clm.status === 'Menunggu Persetujuan Admin' || !clm.status) {
            pendingPointApps.push({ ...clm, custId: cust.id, custNama: cust.nama, custTelp: cust.telepon, custCurrentPoints: cust.poin });
          }
        });
      }
    });

    if (pendingPointApps.length > 0) {
      pointAppContainer.style.display = 'block';
      if (pointAppBadgeEl) pointAppBadgeEl.textContent = `${pendingPointApps.length} Klaim Menunggu`;

      pointAppListEl.innerHTML = pendingPointApps.map(app => {
        const tglStr = new Date(app.tanggal).toLocaleDateString('id-ID');

        return `
          <div style="background: #fff; border: 1px solid #fcd34d; border-radius: 10px; padding: 0.85rem 1rem; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 0.75rem;">
            <div>
              <div style="display: flex; align-items: center; gap: 0.5rem; flex-wrap: wrap;">
                <strong style="font-size: 0.95rem; color: #92400e;">${escapeHtml(app.custNama || 'Anggota')}</strong>
                <span style="font-size: 0.75rem; background: #fef3c7; color: #b45309; padding: 0.15rem 0.5rem; border-radius: 999px; font-weight: 700;">${app.custTelp || 'No HP -'}</span>
                <span style="font-size: 0.75rem; color: var(--text-muted);">Tgl: ${tglStr}</span>
                <span style="font-size: 0.73rem; background: #fef3c7; color: #b45309; padding: 0.15rem 0.5rem; border-radius: 6px; font-weight: 700;">Klaim Poin Mandiri</span>
              </div>
              <div style="font-size: 0.84rem; color: var(--text-main); margin-top: 0.3rem;">
                <b>Klaim Poin:</b> <span style="font-size: 1.05rem; font-weight: 900; color: #d97706; font-family: monospace;">${formatRupiah(app.poin)} Poin</span>
                <span style="margin-left: 0.5rem; font-size: 1.05rem; font-weight: 900; color: #16a34a; font-family: monospace;">(Rp ${formatRupiah(app.nilai_rupiah)})</span>
                <span style="margin-left: 0.75rem; color: var(--text-muted); font-size: 0.78rem;">| Saldo Poin Sekarang: <b>${formatRupiah(app.custCurrentPoints || 0)} Poin</b></span>
              </div>
              ${app.detail_bank ? `<div style="font-size: 0.78rem; color: #0369a1; margin-top: 0.2rem; font-weight: 600;"><b>Rekening/Tujuan:</b> ${escapeHtml(app.detail_bank)}</div>` : ''}
              ${app.catatan ? `<div style="font-size: 0.78rem; color: var(--text-muted); margin-top: 0.15rem;"><b>Catatan:</b> ${escapeHtml(app.catatan)}</div>` : ''}
            </div>
            <div style="display: flex; gap: 0.45rem;">
              <button type="button" onclick="approveMemberPointApplication('${app.id}', '${app.custId}')" style="background: #d97706; color: #fff; border: none; font-weight: 800; font-size: 0.82rem; padding: 0.5rem 0.95rem; border-radius: 8px; cursor: pointer; display: inline-flex; align-items: center; gap: 0.35rem; box-shadow: 0 2px 4px rgba(217,119,6,0.25);">
                <span>✓ ACC &amp; Cairkan Poin</span>
              </button>
              <button type="button" onclick="rejectMemberPointApplication('${app.id}', '${app.custId}')" style="background: #dc2626; color: #fff; border: none; font-weight: 800; font-size: 0.82rem; padding: 0.5rem 0.85rem; border-radius: 8px; cursor: pointer; display: inline-flex; align-items: center; gap: 0.35rem;">
                <span>✕ Tolak</span>
              </button>
            </div>
          </div>
        `;
      }).join('');
    } else {
      pointAppContainer.style.display = 'none';
    }
  }

  // Filter tampilan sesuai tab aktif
  let displayTxs = debtTxs;
  if (currentCustomerDebtFilter === 'unpaid') {
    displayTxs = debtTxs.filter(tx => (tx.sisa_piutang || 0) > 0);
  } else if (currentCustomerDebtFilter === 'paid') {
    displayTxs = debtTxs.filter(tx => (tx.sisa_piutang || 0) <= 0);
  } else if (currentCustomerDebtFilter === 'overdue') {
    displayTxs = debtTxs.filter(tx => (tx.sisa_piutang || 0) > 0 && tx.jatuh_tempo && tx.jatuh_tempo <= todayStr);
  }

  // Filter Pencarian Nama Pelanggan / ID Transaksi / Produk
  const searchInput = document.getElementById('debt-search-customer');
  const query = (searchInput?.value || '').trim().toLowerCase();
  if (query) {
    displayTxs = displayTxs.filter(tx => {
      const matchName = (tx.nama_pelanggan || '').toLowerCase().includes(query);
      const matchId = (tx.id || '').toLowerCase().includes(query);
      const matchItems = Array.isArray(tx.items) && tx.items.some(it => (it.nama || '').toLowerCase().includes(query));
      const matchNotes = (tx.catatan_bon || '').toLowerCase().includes(query);
      return matchName || matchId || matchItems || matchNotes;
    });
  }

  // Urutkan secara default berdasarkan hutang yang terbaru
  displayTxs.sort((a, b) => {
    const timeA = a.waktu ? new Date(a.waktu).getTime() : 0;
    const timeB = b.waktu ? new Date(b.waktu).getTime() : 0;
    return timeB - timeA; // Paling baru di atas
  });

  tbody.innerHTML = '';

  if (displayTxs.length === 0) {
    // Tampilkan info berapa total transaksi ada
    const totalTx = txSource.length;
    tbody.innerHTML = `
      <tr>
        <td colspan="7" style="text-align: center; padding: 2.5rem 1rem;">
          <div style="font-size: 2rem; margin-bottom: 0.5rem;">🎉</div>
          <div style="font-weight: 700; color: var(--text-main); font-size: 0.95rem;">Tidak Ada Data Piutang</div>
          <div style="font-size: 0.8rem; margin-top: 0.25rem; color: #64748b;">
            ${currentCustomerDebtFilter === 'unpaid' ? 'Semua hutang sudah lunas atau belum ada transaksi Bon.' : 'Tidak ada data hutang yang cocok dengan filter.'}
          </div>
          <div style="font-size: 0.75rem; margin-top: 0.5rem; color: #94a3b8;">(Total transaksi tersimpan: ${totalTx})</div>
        </td>
      </tr>
    `;
    return;
  }


  displayTxs.forEach(tx => {
    const tr = document.createElement('tr');
    const sisa = tx.sisa_piutang || 0;
    const isLunas = sisa <= 0;
    const waktuStr = formatDateTimeIndo(tx.waktu);
    const dueDate = tx.jatuh_tempo ? formatDateIndo(tx.jatuh_tempo) : '-';
    const isOverdue = !isLunas && tx.jatuh_tempo && (tx.jatuh_tempo < todayStr);
    const isDueToday = !isLunas && tx.jatuh_tempo && (tx.jatuh_tempo === todayStr);

    let dueBadgeHtml = `<span style="font-size: 0.82rem; font-family: monospace;">${dueDate}</span>`;
    if (isOverdue) {
      dueBadgeHtml += `<div style="font-size: 0.7rem; color: #dc2626; font-weight: 700; background: #fef2f2; padding: 0.1rem 0.4rem; border-radius: 4px; display: inline-block; margin-top: 2px;">⚠️ Lewat Jatuh Tempo</div>`;
    } else if (isDueToday) {
      dueBadgeHtml += `<div style="font-size: 0.7rem; color: #d97706; font-weight: 700; background: #fffbeb; padding: 0.1rem 0.4rem; border-radius: 4px; display: inline-block; margin-top: 2px;">⏰ Jatuh Tempo Hari Ini</div>`;
    }

    // Rincian produk yang dihutang
    let productsHtml = '';
    if (Array.isArray(tx.items) && tx.items.length > 0) {
      productsHtml = `<div style="display: flex; flex-direction: column; gap: 3px; max-width: 250px;">`;
      tx.items.forEach(it => {
        const itemSubtotal = it.subtotal !== undefined ? it.subtotal : ((it.harga || 0) * (it.qty || 1));
        productsHtml += `
          <div style="font-size: 0.78rem; line-height: 1.3; color: var(--text-main); display: flex; justify-content: space-between; gap: 6px; border-bottom: 1px dotted var(--border-color); padding-bottom: 2px;">
            <span>• <b>${it.nama}</b> <span style="color:var(--text-muted);">&times;${it.qty || 1}</span></span>
            <span style="font-weight: 600; white-space: nowrap; color: #64748b;">Rp ${formatRupiah(itemSubtotal)}</span>
          </div>
        `;
      });
      productsHtml += `</div>`;
    } else {
      productsHtml = `<span style="font-size: 0.78rem; color: var(--text-muted); font-style: italic;">Hutang Manual (Tanpa Rincian POS)</span>`;
    }

    // Riwayat pelunasan & tanggal lunas
    let settlementHistoryHtml = '';
    const hasHistory = Array.isArray(tx.riwayat_pelunasan) && tx.riwayat_pelunasan.length > 0;
    if (isLunas) {
      let lunasDateStr = '-';
      if (hasHistory) {
        const lastPayment = tx.riwayat_pelunasan[tx.riwayat_pelunasan.length - 1];
        if (lastPayment && lastPayment.waktu) {
          lunasDateStr = formatDateTimeIndo(lastPayment.waktu);
        }
      }
      settlementHistoryHtml = `
        <div style="margin-top: 4px; font-size: 0.73rem; color: #059669; background: #ecfdf5; padding: 0.25rem 0.5rem; border-radius: 6px; border: 1px solid #a7f3d0;">
          <div><b>✓ Lunas pada:</b> ${lunasDateStr}</div>
          ${hasHistory ? `<div style="font-size: 0.7rem; color: #047857; margin-top: 2px;">Melunasi seluruh produk di transaksi ini (${tx.riwayat_pelunasan.length}x pembayaran)</div>` : ''}
        </div>
      `;
    } else if (hasHistory) {
      let totalPaidSoFar = tx.riwayat_pelunasan.reduce((sum, p) => sum + (p.bayar || 0), 0);
      const lastPayment = tx.riwayat_pelunasan[tx.riwayat_pelunasan.length - 1];
      const lastPaymentStr = lastPayment && lastPayment.waktu ? parseTxDate(lastPayment.waktu).toLocaleDateString('id-ID') : '-';
      settlementHistoryHtml = `
        <div style="margin-top: 4px; font-size: 0.72rem; color: #0284c7; background: #f0f9ff; padding: 0.25rem 0.5rem; border-radius: 6px; border: 1px solid #bae6fd;">
          <div><b>Dicicil:</b> Rp ${formatRupiah(totalPaidSoFar)}</div>
          <div style="font-size: 0.68rem; color: #0369a1;">Terakhir: ${lastPaymentStr}</div>
        </div>
      `;
    }

    let statusBadgeHtml = isLunas
      ? `<span style="font-size: 0.75rem; color: #059669; background: #ecfdf5; font-weight: 800; padding: 0.2rem 0.6rem; border-radius: 999px; border: 1px solid #a7f3d0; display: inline-block;">Lunas</span>`
      : `<span style="font-size: 0.75rem; color: #dc2626; background: #fef2f2; font-weight: 800; padding: 0.2rem 0.6rem; border-radius: 999px; border: 1px solid #fecaca; display: inline-block;">Belum Lunas</span>`;

    let actionBtnHtml = '';
    if (isLunas) {
      actionBtnHtml = `
        <button type="button" class="btn btn-warning btn-sm" onclick="toggleDebtPaymentStatus('${tx.id}')" title="Ubah status menjadi Belum Lunas" style="font-size: 0.75rem; font-weight: 700; padding: 0.35rem 0.65rem; border-radius: 6px; background: #f59e0b; border-color: #f59e0b; color: #fff; display: inline-flex; align-items: center; gap: 0.25rem;">
          <span>↩ Buka Hutang</span>
        </button>
        <button type="button" class="btn btn-secondary btn-sm" onclick="showReceipt(transactions.find(t=>t.id==='${tx.id}'), transactions.find(t=>t.id==='${tx.id}')?.items)" title="Lihat Struk Transaksi Lengkap" style="font-size: 0.75rem; padding: 0.35rem 0.65rem; border-radius: 6px; display: inline-flex; align-items: center; gap: 0.25rem;">
          <i data-lucide="receipt" style="width: 13px; height: 13px;"></i>
          <span>Struk</span>
        </button>
        <button type="button" class="btn btn-danger btn-sm" onclick="deleteCustomerDebt('${tx.id}')" title="Hapus Catatan Hutang Ini" style="font-size: 0.75rem; padding: 0.35rem 0.6rem; border-radius: 6px; display: inline-flex; align-items: center; gap: 0.25rem; background: #ef4444; border-color: #ef4444; color: #fff;">
          <i data-lucide="trash-2" style="width: 13px; height: 13px;"></i>
          <span>Hapus</span>
        </button>
      `;
    } else {
      actionBtnHtml = `
        <button type="button" class="btn btn-primary btn-sm" onclick="openPayDebtModal('${tx.id}')" title="Bayar / Cicil Hutang Transaksi Ini" style="font-size: 0.78rem; font-weight: 700; padding: 0.35rem 0.7rem; border-radius: 6px; background: #10b981; border-color: #10b981; display: inline-flex; align-items: center; gap: 0.25rem;">
          <svg viewBox="0 0 24 24" style="width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 2.2;"><rect x="1" y="4" width="22" height="16" rx="2" ry="2"/><line x1="1" y1="10" x2="23" y2="10"/></svg>
          <span>Bayar</span>
        </button>
        <button type="button" class="btn btn-success btn-sm" onclick="sendWhatsAppDebtReminder('${tx.id}')" title="Kirim Tagihan &amp; Rincian Bon via WhatsApp" style="font-size: 0.75rem; font-weight: 700; padding: 0.35rem 0.65rem; border-radius: 6px; background: #25d366; border-color: #25d366; color: #fff; display: inline-flex; align-items: center; gap: 0.25rem;">
          <span>💬 WA</span>
        </button>
        <button type="button" class="btn btn-secondary btn-sm" onclick="toggleDebtPaymentStatus('${tx.id}')" title="Ubah status langsung jadi Lunas" style="font-size: 0.75rem; font-weight: 600; padding: 0.35rem 0.5rem; border-radius: 6px;">
          <span>⚡ Lunas</span>
        </button>
        <button type="button" class="btn btn-danger btn-sm" onclick="deleteCustomerDebt('${tx.id}')" title="Hapus Catatan Hutang Ini" style="font-size: 0.75rem; padding: 0.35rem 0.6rem; border-radius: 6px; display: inline-flex; align-items: center; gap: 0.25rem; background: #ef4444; border-color: #ef4444; color: #fff;">
          <i data-lucide="trash-2" style="width: 13px; height: 13px;"></i>
          <span>Hapus</span>
        </button>
      `;
    }

    const noteText = tx.catatan_bon ? `<div style="font-size: 0.73rem; color: var(--text-muted); font-style: italic; margin-top: 2px;">Catatan: ${tx.catatan_bon}</div>` : '';

    tr.style.borderBottom = '1px solid var(--border-color)';
    tr.style.transition = 'background 0.15s ease';
    tr.innerHTML = `
      <td style="padding: 0.75rem 1rem; vertical-align: middle;">
        <strong style="color: var(--text-main); font-size: 0.9rem; display: block; line-height: 1.3;">${tx.nama_pelanggan || 'Pelanggan Umum'}</strong>
        ${noteText}
      </td>
      <td style="padding: 0.75rem 1rem; vertical-align: middle;">
        <div style="font-family: monospace; font-size: 0.82rem; font-weight: 700; color: #ea580c;">${tx.id}</div>
        <div style="font-size: 0.74rem; color: var(--text-muted); margin-top: 2px; display: flex; align-items: center; gap: 3px;">
          <i data-lucide="clock" style="width: 11px; height: 11px;"></i> ${waktuStr}
        </div>
      </td>
      <td style="padding: 0.75rem 1rem; vertical-align: middle;">
        ${productsHtml}
      </td>
      <td style="padding: 0.75rem 1rem; vertical-align: middle;">
        ${dueBadgeHtml}
      </td>
      <td style="padding: 0.75rem 1rem; vertical-align: middle; text-align: right; font-family: 'JetBrains Mono', monospace, sans-serif; font-size: 0.88rem; font-weight: 700; color: var(--text-main);">
        Rp ${formatRupiah(tx.total || 0)}
      </td>
      <td style="padding: 0.75rem 1rem; vertical-align: middle; text-align: right; font-family: 'JetBrains Mono', monospace, sans-serif; font-size: 0.94rem; font-weight: 900; color: ${isLunas ? '#059669' : '#dc2626'};">
        Rp ${formatRupiah(sisa)}
      </td>
      <td style="padding: 0.75rem 1rem; vertical-align: middle; text-align: center;">
        ${statusBadgeHtml}
        ${settlementHistoryHtml}
      </td>
      <td style="padding: 0.75rem 1rem; vertical-align: middle; text-align: center;">
        <div style="display: inline-flex; gap: 0.35rem; align-items: center; justify-content: center; flex-wrap: wrap;">
          ${actionBtnHtml}
        </div>
      </td>
    `;
    tbody.appendChild(tr);
  });
  if (typeof lucide !== 'undefined' && lucide.createIcons) {
    try { lucide.createIcons(); } catch(e) {}
  }
}

// 4. Modal Pelunasan Hutang Member Langsung di CRM
async function openPayDebtModal(txId) {
  const tx = transactions.find(t => t.id === txId);
  if (!tx) {
    alert("Transaksi tidak ditemukan!");
    return;
  }

  const sisa = tx.sisa_piutang || 0;
  if (sisa <= 0) {
    alert("Tagihan transaksi ini sudah lunas!");
    return;
  }

  document.getElementById('pay-debt-tx-id').value = tx.id;
  document.getElementById('pay-debt-cust-name').value = tx.nama_pelanggan || '';
  document.getElementById('pay-debt-display-name').textContent = tx.nama_pelanggan || 'Pelanggan Umum';
  document.getElementById('pay-debt-display-tx').textContent = tx.id;
  document.getElementById('pay-debt-display-due').textContent = tx.jatuh_tempo || 'Tanpa Jatuh Tempo';
  document.getElementById('pay-debt-display-balance').textContent = `Rp ${formatRupiah(sisa)}`;

  const amountInput = document.getElementById('pay-debt-amount');
  if (amountInput) {
    amountInput.value = formatRupiah(sisa);
    amountInput.dataset.max = sisa;
  }
  const notesInput = document.getElementById('pay-debt-notes');
  if (notesInput) notesInput.value = '';

  const modal = document.getElementById('pay-debt-modal');
  if (modal) {
    modal.classList.add('active');
    modal.style.display = 'flex';
    setTimeout(() => {
      if (amountInput) amountInput.focus();
    }, 100);
  }
}

async function closePayDebtModal() {
  const modal = document.getElementById('pay-debt-modal');
  if (modal) {
    modal.classList.remove('active');
    modal.style.display = 'none';
  }
}

async function setPayDebtFullAmount() {
  const amountInput = document.getElementById('pay-debt-amount');
  const maxSisa = parseFloat(amountInput?.dataset?.max) || 0;
  if (amountInput && maxSisa > 0) {
    amountInput.value = formatRupiah(maxSisa);
  }
}

let isSubmittingPayDebt = false;

async function submitPayDebt(event) {
  if (event) event.preventDefault();
  if (isSubmittingPayDebt) return;

  const submitBtn = document.querySelector('#pay-debt-modal button[type="submit"]');
  const txId = document.getElementById('pay-debt-tx-id').value;
  const tx = transactions.find(t => t.id === txId);
  if (!tx) return;

  const rawAmount = document.getElementById('pay-debt-amount').value.replace(/\./g, '');
  const payAmount = parseFloat(rawAmount) || 0;
  const payMethod = document.getElementById('pay-debt-method')?.value || 'Tunai';
  const payNotes = (document.getElementById('pay-debt-notes')?.value || '').trim();

  if (payAmount <= 0) {
    alert("Jumlah pembayaran harus lebih dari Rp 0!");
    return;
  }

  try {
    isSubmittingPayDebt = true;
    if (submitBtn) {
      submitBtn.disabled = true;
      submitBtn.textContent = 'Menyimpan...';
    }

    const sisaSebelumnya = tx.sisa_piutang || 0;
    const sisaBaru = Math.max(0, sisaSebelumnya - payAmount);
    tx.sisa_piutang = sisaBaru;

    if (sisaBaru <= 0) {
      tx.status_pembayaran = 'Lunas';
    }

    if (!Array.isArray(tx.riwayat_pelunasan)) {
      tx.riwayat_pelunasan = [];
    }

    const pelunasanEntry = {
      waktu: new Date().toISOString(),
      bayar: payAmount,
      metode: payMethod,
      kasir: activeCashier || 'Admin',
      catatan: payNotes || (sisaBaru <= 0 ? 'Pelunasan Penuh' : 'Cicilan Hutang')
    };
    tx.riwayat_pelunasan.push(pelunasanEntry);

    // Jika dibayar Tunai, otomatis catat kas masuk ke Laci Kasir agar klop saat tutup shift
    if (payMethod === 'Tunai') {
      const debtCashExpense = {
        id: 'EXP_' + Date.now(),
        tanggal: new Date().toISOString(),
        tipe: 'masuk',
        nominal: payAmount,
        kategori: 'Pelunasan Piutang',
        is_debt_payment: true,
        txId: tx.id,
        sumberDana: 'laci_kasir',
        keterangan: `Pelunasan Bon #${tx.id} (${tx.nama_pelanggan || 'Pelanggan'})`,
        staff: activeCashier || 'Admin'
      };
      if (!Array.isArray(expenses)) expenses = [];
      expenses.unshift(debtCashExpense);
      saveExpensesLocally();
      if (firebaseDb && typeof getStorePath === 'function') {
        firebaseDb.ref(getStorePath('expenses/' + debtCashExpense.id)).set(debtCashExpense);
      }
    }

    saveTransactionsLocally();
    renderCustomerDebtBook();
    renderTransactionsTable();
    updateAnalytics();

    // Sinkronkan update transaksi ke Cloud jika aktif
    syncSingleTransactionToCloud(tx);

    alert(`✅ Pembayaran sebesar Rp ${formatRupiah(payAmount)} berhasil dicatat!\n• Sisa Hutang: Rp ${formatRupiah(sisaBaru)}\n• Status: ${tx.status_pembayaran}`);
    closePayDebtModal();
  } finally {
    isSubmittingPayDebt = false;
    if (submitBtn) {
      submitBtn.disabled = false;
      submitBtn.textContent = 'Simpan Pembayaran';
    }
  }
}

// Cepat tandai lunas transaksi hutang
async function quickPayFullDebt(txId) {
  const tx = transactions.find(t => t.id === txId);
  if (!tx) return;
  const sisa = tx.sisa_piutang || 0;
  if (sisa <= 0) {
    alert("Transaksi ini sudah lunas!");
    return;
  }

  if (await showAppConfirm('Konfirmasi pelunasan penuh sebesar Rp ' + formatRupiah(sisa) + ' untuk ' + (tx.nama_pelanggan || 'Pelanggan') + '?', { title: 'Pelunasan Hutang', isDanger: false, confirmClass: 'btn btn-primary', confirmText: 'Ya, Lunaskan' })) {
    tx.sisa_piutang = 0;
    tx.status_pembayaran = 'Lunas';

    if (!Array.isArray(tx.riwayat_pelunasan)) tx.riwayat_pelunasan = [];
    tx.riwayat_pelunasan.push({
      waktu: new Date().toISOString(),
      bayar: sisa,
      metode: 'Tunai',
      kasir: activeCashier || 'Admin',
      catatan: 'Pelunasan Cepat Penuh'
    });

    saveTransactionsLocally();

    // Otomatis catat kas masuk ke Laci Kasir agar klop saat tutup shift
    const debtCashExpense = {
      id: 'EXP_' + Date.now(),
      tanggal: new Date().toISOString(),
      tipe: 'masuk',
      nominal: sisa,
      kategori: 'Pelunasan Piutang',
      is_debt_payment: true,
      txId: tx.id,
      sumberDana: 'laci_kasir',
      keterangan: `Pelunasan Bon #${tx.id} (${tx.nama_pelanggan || 'Pelanggan'})`,
      staff: activeCashier || 'Admin'
    };
    if (!Array.isArray(expenses)) expenses = [];
    expenses.unshift(debtCashExpense);
    saveExpensesLocally();
    if (firebaseDb && typeof getStorePath === 'function') {
      firebaseDb.ref(getStorePath('expenses/' + debtCashExpense.id)).set(debtCashExpense);
    }

    renderCustomerDebtBook();
    renderTransactionsTable();
    updateAnalytics();
    syncSingleTransactionToCloud(tx);
    alert(`✅ Tagihan sebesar Rp ${formatRupiah(sisa)} berhasil dilunasi!`);
  }
}

// Ubah status hutang: Lunas -> Belum Lunas atau sebaliknya
async function toggleDebtPaymentStatus(txId) {
  const tx = transactions.find(t => t.id === txId);
  if (!tx) {
    alert("Transaksi tidak ditemukan!");
    return;
  }

  const isLunas = (tx.sisa_piutang === 0 || tx.status_pembayaran === 'Lunas');

  if (isLunas) {
    if (!(await showAppConfirm('Apakah Anda yakin ingin mengubah status hutang transaksi #' + tx.id + ' (' + (tx.nama_pelanggan || 'Pelanggan') + ') menjadi BELUM LUNAS?', { title: 'Ubah Status Hutang' }))) {
      return;
    }

    // Hitung DP awal transaksi asli jika ada
    const dpAwal = Math.max(0, (Number(tx.bayar) || 0) - (Number(tx.kembalian) || 0));
    const totalTagihan = Number(tx.total) || 0;
    const sisaKembali = Math.max(0, totalTagihan - dpAwal);

    tx.sisa_piutang = sisaKembali;
    tx.status_pembayaran = 'Bon';

    // Kosongkan riwayat pelunasan
    tx.riwayat_pelunasan = [];

    // Hapus pencatatan kas pelunasan piutang di expenses
    if (Array.isArray(expenses)) {
      const prevCount = expenses.length;
      expenses = expenses.filter(e => {
        if (!e) return false;
        const matchKeterangan = (e.keterangan || '').includes(`Bon #${tx.id}`) || (e.keterangan || '').includes(tx.id);
        const isLinkedDebtExpense = (e.is_debt_payment === true || (e.kategori && e.kategori.toLowerCase().includes('pelunasan piutang'))) && matchKeterangan;
        return !isLinkedDebtExpense;
      });
      if (expenses.length !== prevCount) {
        saveExpensesLocally();
        if (typeof syncExpensesToCloud === 'function') syncExpensesToCloud();
      }
    }

    saveTransactionsLocally();
    syncSingleTransactionToCloud(tx);
    renderCustomerDebtBook();
    renderTransactionsTable();
    updateAnalytics();

    alert(`✅ Status transaksi #${tx.id} berhasil diubah menjadi BELUM LUNAS (Sisa: Rp ${formatRupiah(sisaKembali)}).`);
  } else {
    // Belum Lunas -> Ubah menjadi Lunas
    quickPayFullDebt(txId);
  }
}

// Hapus catatan hutang dari Buku Hutang
async function deleteCustomerDebt(txId) {
  if (!canPerformAction('deleteTx')) {
    alert("⛔ Akses Ditolak: Anda tidak memiliki izin untuk menghapus catatan hutang/transaksi!");
    return;
  }

  const tx = transactions.find(t => t.id === txId);
  if (!tx) {
    alert("Catatan hutang tidak ditemukan!");
    return;
  }

  const debtor = tx.nama_pelanggan || 'Pelanggan';
  const sisaStr = tx.sisa_piutang ? `sebesar Rp ${formatRupiah(tx.sisa_piutang)}` : '';
  const isManual = tx.is_manual_debt === true || (Array.isArray(tx.items) && tx.items.length === 0);

  const confirmMsg = isManual
    ? `⚠️ Hapus Catatan Hutang Manual?\n\nDebitur: ${debtor} ${sisaStr}\nCatatan: ${tx.catatan_bon || '-'}\n\nApakah Anda yakin ingin menghapus catatan hutang ini secara permanen?`
    : `⚠️ Hapus Catatan Hutang Transaksi "${txId}"?\n\nPelanggan: ${debtor} ${sisaStr}\n\nPerhatian: Transaksi ini memiliki barang penjualan. Menghapus hutang ini akan membatalkan transaksi dan mengembalikan seluruh stok barang ke toko.\n\nLanjutkan hapus?`;

  if (!await showAppConfirm(confirmMsg, { title: "Hapus Catatan Hutang" })) return;

  // Gunakan fungsi deleteTransaction yang sudah aman menangani pengembalian stok (termasuk bundling) dan sync cloud
  await deleteTransaction(txId);
  renderCustomerDebtBook();
}

// 5. Cetak Laporan Rekapitulasi Piutang & Hutang Member (Super Lengkap: Rincian Barang, Pembayaran, Pelunasan)
function printCustomerDebtReport() {
  const dateStart = document.getElementById('filter-debt-date-start')?.value || '';
  const dateEnd = document.getElementById('filter-debt-date-end')?.value || '';
  const now = new Date();
  const todayStr = getLocalISODate(now).slice(0, 10);

  let txSource = transactions;
  if (typeof analyticsTransactions !== 'undefined' && Array.isArray(analyticsTransactions) && analyticsTransactions.length > 0) {
    txSource = analyticsTransactions;
  }

  let debtTxs = txSource.filter(tx => {
    const isBon = tx.status_pembayaran === 'Bon' || (tx.sisa_piutang > 0);
    const wasEverBon = Array.isArray(tx.riwayat_pelunasan) && tx.riwayat_pelunasan.length > 0;
    return isBon || wasEverBon;
  });

  // Filter Rentang Tanggal jika diisi
  if (dateStart || dateEnd) {
    debtTxs = debtTxs.filter(tx => {
      if (!tx.waktu) return false;
      const tgl = parseTxDateStr(tx.waktu).slice(0, 10);
      if (dateStart && tgl < dateStart) return false;
      if (dateEnd && tgl > dateEnd) return false;
      return true;
    });
  }

  if (currentCustomerDebtFilter === 'unpaid') {
    debtTxs = debtTxs.filter(tx => (tx.sisa_piutang || 0) > 0);
  } else if (currentCustomerDebtFilter === 'paid') {
    debtTxs = debtTxs.filter(tx => (tx.sisa_piutang || 0) <= 0);
  }

  if (debtTxs.length === 0) {
    alert("Tidak ada data piutang untuk dicetak pada periode ini.");
    return;
  }

  // Urutkan berdasarkan waktu transaksi terbaru
  debtTxs.sort((a, b) => {
    const timeA = a.waktu ? new Date(a.waktu).getTime() : 0;
    const timeB = b.waktu ? new Date(b.waktu).getTime() : 0;
    return timeB - timeA;
  });

  let totalUnpaid = 0;
  let totalPaid = 0;
  let totalTagihanAwal = 0;
  let rowsHtml = '';

  debtTxs.forEach((tx, idx) => {
    const sisa = Number(tx.sisa_piutang) || 0;
    const isLunas = sisa <= 0;
    const totalTx = Number(tx.total) || 0;
    const dpBayarAwal = Math.max(0, (Number(tx.bayar) || 0) - (Number(tx.kembalian) || 0));

    totalTagihanAwal += totalTx;
    if (isLunas) totalPaid += totalTx;
    else totalUnpaid += sisa;

    const tglPinjam = tx.waktu ? parseTxDateStr(tx.waktu) : '-';
    const tempo = tx.jatuh_tempo || '-';
    const statusText = isLunas ? 'LUNAS' : 'BELUM LUNAS';
    const statusColor = isLunas ? '#059669' : '#dc2626';

    // Rincian Barang yang Dihutang
    let itemsDetailHtml = '';
    if (Array.isArray(tx.items) && tx.items.length > 0) {
      itemsDetailHtml = '<ul style="margin: 0; padding-left: 14px; list-style-type: square; font-size: 11px;">';
      tx.items.forEach(it => {
        const qtyPcs = Number(it.qty) || 0;
        const hargaSatuan = Number(it.harga) || 0;
        const subtotal = it.subtotal !== undefined ? Number(it.subtotal) : (qtyPcs * hargaSatuan);
        itemsDetailHtml += `<li><b>${escapeHtml(it.nama || 'Produk')}</b>: ${qtyPcs} pcs &times; Rp ${formatRupiah(hargaSatuan)} = <b>Rp ${formatRupiah(subtotal)}</b></li>`;
      });
      itemsDetailHtml += '</ul>';
    } else {
      itemsDetailHtml = `<span style="color: #64748b; font-style: italic;">Hutang Manual / Pinjaman Kas: ${escapeHtml(tx.catatan_bon || tx.keterangan_manual || '-')}</span>`;
    }

    // Rincian Riwayat Pembayaran & Kapan Lunas
    let paymentHistoryHtml = '';
    let tglLunasStr = '-';
    let totalSudahDibayar = 0;

    if (Array.isArray(tx.riwayat_pelunasan) && tx.riwayat_pelunasan.length > 0) {
      paymentHistoryHtml = '<div style="margin-top: 4px; font-size: 10.5px; color: #334155; line-height: 1.35;">';
      if (dpBayarAwal > 0) {
        paymentHistoryHtml += `<div>• DP Awal: Rp ${formatRupiah(dpBayarAwal)}</div>`;
        totalSudahDibayar += dpBayarAwal;
      }
      tx.riwayat_pelunasan.forEach((p, pIdx) => {
        const pTgl = p.waktu ? new Date(p.waktu).toLocaleString('id-ID', { dateStyle: 'short', timeStyle: 'short' }) : '-';
        const pNom = Number(p.bayar) || 0;
        totalSudahDibayar += pNom;
        paymentHistoryHtml += `<div>• Bayar ${pIdx + 1} (${pTgl}): <b>Rp ${formatRupiah(pNom)}</b> [${p.metode || 'Tunai'}]</div>`;
      });
      paymentHistoryHtml += '</div>';

      if (isLunas) {
        const lastPay = tx.riwayat_pelunasan[tx.riwayat_pelunasan.length - 1];
        if (lastPay && lastPay.waktu) {
          tglLunasStr = new Date(lastPay.waktu).toLocaleDateString('id-ID', { dateStyle: 'medium' });
        }
      }
    } else if (dpBayarAwal > 0) {
      paymentHistoryHtml = `<div style="font-size: 10.5px; color: #334155;">• Uang Muka / DP: Rp ${formatRupiah(dpBayarAwal)}</div>`;
      totalSudahDibayar = dpBayarAwal;
      if (isLunas) tglLunasStr = tglPinjam;
    } else if (isLunas) {
      tglLunasStr = tglPinjam;
      totalSudahDibayar = totalTx;
    }

    rowsHtml += `
      <tr style="border-bottom: 1px solid #cbd5e1; page-break-inside: avoid;">
        <td style="padding: 8px 6px; text-align: center; vertical-align: top; font-weight: bold; color: #64748b;">${idx + 1}</td>
        <td style="padding: 8px 6px; vertical-align: top;">
          <strong style="font-size: 12px; color: #0f172a;">${escapeHtml(tx.nama_pelanggan || 'Pelanggan Umum')}</strong>
          ${tx.id_pelanggan ? `<br><small style="color: #64748b; font-family: monospace;">ID: ${escapeHtml(tx.id_pelanggan)}</small>` : ''}
          <br><small style="color: #475569; font-family: monospace;">#${tx.id}</small>
        </td>
        <td style="padding: 8px 6px; vertical-align: top; line-height: 1.4;">
          ${itemsDetailHtml}
        </td>
        <td style="padding: 8px 6px; vertical-align: top; font-size: 11px;">
          <div><b>Pinjam:</b> ${tglPinjam}</div>
          <div style="color: #dc2626; margin-top: 2px;"><b>Tempo:</b> ${tempo}</div>
          ${isLunas ? `<div style="color: #059669; margin-top: 2px;"><b>Lunas:</b> ${tglLunasStr}</div>` : ''}
        </td>
        <td style="padding: 8px 6px; vertical-align: top; text-align: right; font-family: monospace;">
          <div style="font-weight: 700; color: #0f172a;">Rp ${formatRupiah(totalTx)}</div>
          <small style="color: #059669;">Terbayar: Rp ${formatRupiah(totalSudahDibayar)}</small>
          ${paymentHistoryHtml}
        </td>
        <td style="padding: 8px 6px; vertical-align: top; text-align: right; font-family: monospace; font-weight: 800; font-size: 12px; color: ${sisa > 0 ? '#dc2626' : '#059669'};">
          Rp ${formatRupiah(sisa)}
        </td>
        <td style="padding: 8px 6px; vertical-align: top; text-align: center;">
          <span style="display: inline-block; padding: 3px 8px; border-radius: 999px; font-size: 10px; font-weight: 800; background: ${isLunas ? '#dcfce7' : '#fee2e2'}; color: ${statusColor}; border: 1px solid ${statusColor}40;">
            ${statusText}
          </span>
        </td>
      </tr>
    `;
  });

  let filterText = 'Semua Periode';
  if (dateStart && dateEnd) {
    filterText = (dateStart === dateEnd) ? `Tanggal: ${dateStart}` : `Periode: ${dateStart} s/d ${dateEnd}`;
  } else if (dateStart) {
    filterText = `Mulai Tanggal: ${dateStart}`;
  } else if (dateEnd) {
    filterText = `Sampai Tanggal: ${dateEnd}`;
  }

  const printContent = `
    <!DOCTYPE html>
    <html lang="id">
    <head>
      <meta charset="UTF-8">
      <title>Laporan Rekapitulasi Rincian Hutang &amp; Piutang Member</title>
      <style>
        body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif; padding: 20px; color: #0f172a; font-size: 11px; line-height: 1.4; background: #fff; }
        .no-print { margin-bottom: 18px; text-align: right; }
        .summary-card { display: flex; justify-content: space-between; gap: 10px; flex-wrap: wrap; margin-bottom: 16px; background: #f8fafc; border: 1.5px solid #cbd5e1; padding: 12px 18px; border-radius: 8px; font-size: 12px; font-weight: bold; }
        table { width: 100%; border-collapse: collapse; margin-top: 10px; border: 1px solid #cbd5e1; border-radius: 6px; overflow: hidden; }
        th { background: #f1f5f9; padding: 8px 6px; text-align: left; border: 1px solid #cbd5e1; font-size: 10.5px; text-transform: uppercase; color: #475569; letter-spacing: 0.3px; }
        td { font-size: 11px; border: 1px solid #cbd5e1; padding: 8px 6px; }
        @media print {
          body { padding: 0; }
          .no-print { display: none !important; }
          @page { size: landscape; margin: 10mm; }
        }
      </style>
    </head>
    <body>
      <div class="no-print">
        <button onclick="window.print()" style="padding: 8px 20px; background: #ea580c; color: #fff; border: none; border-radius: 6px; font-weight: bold; cursor: pointer; font-size: 13px;">🖨️ Cetak Dokumen</button>
        <button type="button" onclick="downloadPopupDocJPG()" style="padding: 8px 16px; background: #0284c7; color: #fff; border: none; border-radius: 6px; font-weight: bold; cursor: pointer; font-size: 13px; margin-left: 8px;">🖼️ Simpan JPG</button>
        <script src="lib/html2canvas.min.js"></script>
        <script>
          function downloadPopupDocJPG() {
            const btn = event ? event.target.closest('button') : null;
            if (btn) { btn.textContent = '⏳ Memproses...'; btn.disabled = true; }
            html2canvas(document.body, {
              scale: 2,
              useCORS: true,
              backgroundColor: '#ffffff',
              ignoreElements: function(el) {
                return !!(el.classList && (el.classList.contains('no-print') || el.classList.contains('preview-toolbar')));
              }
            }).then(canvas => {
              const a = document.createElement('a');
              a.href = canvas.toDataURL('image/jpeg', 0.95);
              a.download = 'Laporan_Hutang_Piutang_' + Date.now() + '.jpg';
              document.body.appendChild(a);
              a.click();
              document.body.removeChild(a);
              if (btn) { btn.textContent = '✅ Berhasil!'; setTimeout(() => { btn.innerHTML = '🖼️ Simpan JPG'; btn.disabled = false; }, 2000); }
            }).catch(err => {
              alert('Gagal simpan JPG: ' + err.message);
              if (btn) { btn.innerHTML = '🖼️ Simpan JPG'; btn.disabled = false; }
            });
          }
        </script>
        <button onclick="window.close()" style="padding: 8px 16px; background: #64748b; color: #fff; border: none; border-radius: 6px; font-weight: bold; cursor: pointer; font-size: 13px; margin-left: 8px;">Tutup</button>
      </div>

      ${getStorePrintHeader()}
      <h3 style="text-align: center; margin: 10px 0 3px 0; font-size: 16px; text-transform: uppercase; color: #1e293b;">LAPORAN RINCIAN BUKU HUTANG &amp; PIUTANG MEMBER</h3>
      <div style="text-align: center; font-size: 11px; color: #64748b; margin-bottom: 14px;">${filterText} &bull; Filter Status: <b>${currentCustomerDebtFilter.toUpperCase()}</b> &bull; Total Transaksi: <b>${debtTxs.length}</b></div>
      
      <div class="summary-card">
        <div>Total Nilai Belanja Diutang: <span style="color: #0284c7; font-size: 13px;">Rp ${formatRupiah(totalTagihanAwal)}</span></div>
        <div>Total Sisa Hutang Belum Lunas: <span style="color: #dc2626; font-size: 13px;">Rp ${formatRupiah(totalUnpaid)}</span></div>
        <div>Total Hutang Yang Sudah Lunas: <span style="color: #059669; font-size: 13px;">Rp ${formatRupiah(totalPaid)}</span></div>
      </div>

      <table>
        <thead>
          <tr>
            <th style="width: 30px; text-align: center;">No</th>
            <th style="width: 140px;">Member / Debitur</th>
            <th>Rincian Barang &amp; Qty Belanja</th>
            <th style="width: 130px;">Tgl Pinjam / Jatuh Tempo / Lunas</th>
            <th style="width: 170px; text-align: right;">Total &amp; Riwayat Cicilan</th>
            <th style="width: 110px; text-align: right;">Sisa Hutang</th>
            <th style="width: 85px; text-align: center;">Status</th>
          </tr>
        </thead>
        <tbody>
          ${rowsHtml}
        </tbody>
      </table>
    </body>
    </html>
  `;

  const printWin = window.open('', '_blank', 'width=1050,height=800');
  if (printWin) {
    printWin.document.open();
    printWin.document.write(printContent);
    printWin.document.close();
    printWin.focus();
  } else {
    alert("Popup browser diblokir! Izinkan pop-up untuk mencetak dokumen.");
  }
}

// Filter Cepat Tagihan Jatuh Tempo & Lewat Waktu
function filterOverdueDebts() {
  currentCustomerDebtFilter = 'overdue';
  const btnUnpaid = document.getElementById('btn-debt-filter-unpaid');
  const btnPaid = document.getElementById('btn-debt-filter-paid');
  const btnAll = document.getElementById('btn-debt-filter-all');
  if (btnUnpaid) { btnUnpaid.style.background = 'transparent'; btnUnpaid.style.color = 'var(--text-muted)'; }
  if (btnPaid) { btnPaid.style.background = 'transparent'; btnPaid.style.color = 'var(--text-muted)'; }
  if (btnAll) { btnAll.style.background = '#d97706'; btnAll.style.color = '#fff'; }
  renderCustomerDebtBook();
}

// Kirim Pengingat Tagihan Hutang / Piutang Otomatis ke WhatsApp Pelanggan
async function sendWhatsAppDebtReminder(txId) {
  const tx = transactions.find(t => t.id === txId);
  if (!tx) {
    alert("Data transaksi tidak ditemukan!");
    return;
  }

  const sisa = tx.sisa_piutang || 0;
  if (sisa <= 0) {
    alert("Tagihan ini sudah lunas!");
    return;
  }

  // Cari nomor HP pelanggan dari transaksi atau data master Member
  let phone = tx.telepon_pelanggan || '';
  if (!phone && tx.nama_pelanggan) {
    const cust = customers.find(c => c.nama && c.nama.trim().toLowerCase() === tx.nama_pelanggan.trim().toLowerCase());
    if (cust && cust.telepon) phone = cust.telepon;
  }

  // Jika belum ada nomor HP, tanyakan ke kasir/owner
  if (!phone) {
    phone = await showAppPrompt(`Masukkan Nomor WhatsApp pelanggan "${tx.nama_pelanggan || 'Pelanggan'}":`, '08', { title: "Kirim Nota WhatsApp", placeholder: "08123456789" });
    if (!phone) return;
  }

  let cleanPhone = phone.replace(/[^0-9]/g, '');
  if (cleanPhone.startsWith('0')) cleanPhone = '62' + cleanPhone.slice(1);

  const storeName = (receiptSettings && receiptSettings.name) || 'Toko Kami';
  const storePhone = (receiptSettings && receiptSettings.phone) ? `\nKontak: ${receiptSettings.phone}` : '';
  const customerName = tx.nama_pelanggan || 'Bapak/Ibu Pelanggan';
  const dueDateStr = tx.jatuh_tempo || '-';
  const txDateStr = tx.waktu ? parseTxDateStr(tx.waktu) : '-';

  // Rincian barang
  let itemsListText = '';
  if (Array.isArray(tx.items) && tx.items.length > 0) {
    itemsListText = '\n📦 *Rincian Belanjaan:*\n' + tx.items.map(it => `• ${it.nama} (${it.qty}x) = Rp ${formatRupiah(it.subtotal || (it.harga * it.qty))}`).join('\n');
  }

  const msg = 
`Halo Kak *${customerName}*, salam hangat dari *${storeName}* 😊

Kami ingin menginfokan rincian catatan bon / tagihan belanja Anda:
--------------------------------------------
🧾 *No. Transaksi:* #${tx.id}
📅 *Tanggal Belanja:* ${txDateStr}
⏰ *Jatuh Tempo:* ${dueDateStr}
💰 *Total Belanja:* Rp ${formatRupiah(tx.total || 0)}
💳 *Sisa Tagihan:* *Rp ${formatRupiah(sisa)}*
${itemsListText}
--------------------------------------------
Mohon kesediaannya untuk melakukan pembayaran sebelum atau pada tanggal jatuh tempo.

Pembayaran dapat dilakukan langsung di kasir toko atau via transfer.
Terima kasih banyak atas kepercayaannya berbelanja di toko kami! 🙏${storePhone}`;

  const waUrl = `https://api.whatsapp.com/send?phone=${cleanPhone}&text=${encodeURIComponent(msg)}`;
  window.open(waUrl, '_blank');
}

